using System.Collections.Generic;
using RimWorld;
using Verse;
using Verse.Sound;

namespace RimPunkCE
{
    /// <summary>
    /// SoundDefs the code plays directly. Generated by Source/Tools/gen_sounds.py (RPC_Snd_ + the manifest id in CamelCase);
    /// the rest of the audio is data: <see cref="AbilitySoundExtension"/>, ActiveEffectExtension.soundOn/Off/Loop,
    /// QuickhackExtension.landSound and the tools' soundMeleeHit / soundMeleeMiss.
    /// </summary>
    [DefOf]
    public static class RPSoundDefOf
    {
        public static SoundDef RPC_Snd_Electroshock;
        public static SoundDef RPC_Snd_NanoDeflect;
        public static SoundDef RPC_Snd_MantisDeploy;
        public static SoundDef RPC_Snd_ThrowWeapon;
        public static SoundDef RPC_Snd_ThrowReturn;
        public static SoundDef RPC_Snd_QhUploadStart;
        public static SoundDef RPC_Snd_QhUploadLoop;
        public static SoundDef RPC_Snd_QhUploaded;
        public static SoundDef RPC_Snd_QhResisted;
        public static SoundDef RPC_Snd_QhImmune;
        public static SoundDef RPC_Snd_QhTraceAlert;
        public static SoundDef RPC_Snd_QhBlackwallJump;

        static RPSoundDefOf() => DefOfHelper.EnsureInitializedInCtor(typeof(RPSoundDefOf));
    }

    /// <summary>Played when the ability is used (CyberwareAbility.Activate): monowire lashes, the mantis dash, instant buffs.</summary>
    public class AbilitySoundExtension : DefModExtension
    {
        public SoundDef cast;
    }

    public static class RPSound
    {
        /// <summary>One-shot at a pawn. Never throws: a missing sound or an unspawned pawn is simply silent.</summary>
        public static void At(SoundDef def, Pawn pawn)
        {
            if (def == null || pawn == null) return;
            var map = pawn.MapHeld;
            if (map == null) return;
            def.PlayOneShot(new TargetInfo(pawn.PositionHeld, map));
        }

        private static readonly Dictionary<(int, string), int> lastPlayed = new Dictionary<(int, string), int>();

        /// <summary>Like <see cref="At(SoundDef, Pawn)"/> but at most once per <paramref name="minTicks"/> for this pawn (sounds tied to every swing).</summary>
        public static void AtThrottled(SoundDef def, Pawn pawn, int minTicks)
        {
            if (def == null || pawn == null) return;
            int now = Find.TickManager.TicksGame;
            var key = (pawn.thingIDNumber, def.defName);
            if (lastPlayed.TryGetValue(key, out int last) && now - last < minTicks) return;
            lastPlayed[key] = now;
            At(def, pawn);
        }

        public static void At(SoundDef def, Thing thing)
        {
            if (def == null || thing?.MapHeld == null) return;
            def.PlayOneShot(new TargetInfo(thing.PositionHeld, thing.MapHeld));
        }

        public static void At(SoundDef def, Map map, IntVec3 cell)
        {
            if (def == null || map == null || !cell.IsValid) return;
            def.PlayOneShot(new TargetInfo(cell, map));
        }

        /// <summary>For alerts with no place in the world.</summary>
        public static void OnCamera(SoundDef def) => def?.PlayOneShotOnCamera();
    }

    /// <summary>
    /// The sustainers of a looping sound that follows a pawn (sandevistan hum, berserk heartbeat). Kept alive by calling
    /// <see cref="Maintain"/> every second or so; the sound ends by itself if that stops.
    /// </summary>
    public static class RPLoop
    {
        public static Sustainer Maintain(Sustainer current, SoundDef def, Pawn pawn)
        {
            if (def == null || pawn == null || !pawn.Spawned) return Stop(current);
            if (current == null || current.Ended)
                current = def.TrySpawnSustainer(SoundInfo.InMap(pawn, MaintenanceType.PerTickRare));
            current?.Maintain();
            return current;
        }

        public static Sustainer Stop(Sustainer current)
        {
            if (current != null && !current.Ended) current.End();
            return null;
        }
    }

    /// <summary>The quickhack upload hum, one per uploading verb.</summary>
    public static class UploadLoop
    {
        private static readonly Dictionary<Verb, Sustainer> Active = new Dictionary<Verb, Sustainer>();

        public static void Maintain(Verb_Quickhack verb)
        {
            if (verb?.CasterPawn == null) return;
            Active.TryGetValue(verb, out var s);
            Active[verb] = RPLoop.Maintain(s, RPSoundDefOf.RPC_Snd_QhUploadLoop, verb.CasterPawn);
        }

        public static void Stop(Verb_Quickhack verb)
        {
            if (verb == null || !Active.TryGetValue(verb, out var s)) return;
            RPLoop.Stop(s);
            Active.Remove(verb);
        }
    }

    /// <summary>A thrown weapon returning to the thrower's hand.</summary>
    public class Hediff_WeaponThrown : HediffWithComps
    {
        public override void PostRemoved()
        {
            base.PostRemoved();
            if (!pawn.Dead) RPSound.At(RPSoundDefOf.RPC_Snd_ThrowReturn, pawn);
        }
    }
}
